import { LocalStorageService } from '@/storages/local_storage_service';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { UserType } from '@/types/UserType';
import { deleteAllNotificationsIndexDb } from '@/storages/indexed_db_service';
import { AuthResponse } from '@/types';

export async function getUser(): Promise<UserType | null> {
  if (USE_SEED_DATA) return seed.getUser();

  let token;

  // Vérifie si nous sommes côté client avant d'accéder à localStorage
  if (typeof window !== 'undefined') {
    token = LocalStorageService.getToken(); // Accéder à localStorage uniquement côté client
  }
  // Détermine l'origin à utiliser
  const origin = window.origin;

  const response = await fetch(URLS.GET_USER, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
      ...(token && { Authorization: token }),
    },
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const json = (await response.json()) as AuthResponse;
  if (json.etat) {
    const { access_token, ...rest } = json.result.client;
    LocalStorageService.saveToken(access_token);
    json.result.client = rest;
    const client = json.result.client as UserType;
    return client;
  } else {
    LocalStorageService.clearData();
    deleteAllNotificationsIndexDb();
  }

  return null;
}

export async function updateUser(item: any): Promise<AuthResponse> {
  if (USE_SEED_DATA) return seed.updateUser(item);

  try {
    const origin = window.origin;
    let token;

    // Vérifie si nous sommes côté client avant d'accéder à localStorage
    if (typeof window !== 'undefined') {
      token = LocalStorageService.getToken(); // Accéder à localStorage uniquement côté client
    }
    const response = await fetch(URLS.GET_USER, {
      method: 'PUT',
      headers: {
        'Content-Type': 'application/json',
        Origin: origin,
        ...(token && { Authorization: token }),
      },
      body: JSON.stringify(item),
    });

    if (!response.ok) {
      const errorData = await response.json();
      throw new Error(errorData.message || 'Échec de la vérification OTP');
    }

    const data = (await response.json()) as AuthResponse;

    // Stockage du token si présent dans la réponse
    if (data.etat && typeof window !== 'undefined') {
      const { access_token, ...rest } = data.result.client;
      LocalStorageService.saveToken(access_token);
      LocalStorageService.saveUser(rest);
      data.result.client = rest;
    }

    return data;
  } catch (error) {
    console.error('Error in update client:', error);
    throw error; // À gérer dans le composant appelant
  }
}
