'use client';

import { create } from 'zustand';
import { isBrowser } from '@/lib/utils';
import {
  getAllPricingIndexDb,
  saveAllPricingIndexDb,
} from '@/storages/indexed_db_service';
import { PricingType } from '@/types/PricingType';

type PricingStoreType = {
  pricings: PricingType[];
  setPricings: (pricings: PricingType[]) => void;
  init: () => void;
};

export const usePricingStore = create<PricingStoreType>((set) => ({
  pricings: [],
  setPricings: async (pricings: PricingType[]) => {
    if (isBrowser()) {
      await saveAllPricingIndexDb(pricings);
    }
    set({ pricings });
  },

  init: async () => {
    if (isBrowser()) {
      const pricings = await getAllPricingIndexDb();
      set({ pricings });
    }
  },
}));
