import { StatusEnum } from '@/enum/stateTransactionEnum';
import { LocalStorageService } from '@/storages/local_storage_service';
import { AuthResponse, CategoryBlocGameType } from '@/types';
import { Game } from '@/types/GameType';
import { NotificationType } from '@/types/NotificationType';
import { PricingType } from '@/types/PricingType';
import { UserType } from '@/types/UserType';
import {
  buildSeedNotifications,
  buildSeedRanking,
  seedBanners,
  seedOnboarding,
  seedPricings,
  seedPromocodes,
  seedReviews,
} from './content';
import { buildSeedCategoryBlocs, buildSeedGames, seedCategories } from './games';

type SeedDb = { users: Record<string, UserType> };

const DB_KEY = 'seed_db';
const TOKEN_PREFIX = 'Bearer seed-';
const LATENCY_MS = 150;

const isBrowser = () => typeof window !== 'undefined';
const wait = () => new Promise((resolve) => setTimeout(resolve, LATENCY_MS));

function readDb(): SeedDb {
  if (!isBrowser()) return { users: {} };
  const raw = localStorage.getItem(DB_KEY);
  return raw ? (JSON.parse(raw) as SeedDb) : { users: {} };
}

function writeDb(db: SeedDb) {
  if (isBrowser()) localStorage.setItem(DB_KEY, JSON.stringify(db));
}

function currentUserId(): string | null {
  if (!isBrowser()) return null;
  const token = LocalStorageService.getToken();
  return token?.startsWith(TOKEN_PREFIX)
    ? token.slice(TOKEN_PREFIX.length)
    : null;
}

function getCurrentUser(): UserType | null {
  const id = currentUserId();
  return id ? (readDb().users[id] ?? null) : null;
}

function saveUser(user: UserType) {
  const db = readDb();
  db.users[user.id] = user;
  writeDb(db);
}

function createUser(phoneNumber = ''): UserType {
  return {
    id: `${Date.now()}`,
    full_name: '',
    pseudo: '',
    email: '',
    phone_number: phoneNumber,
    profil: 'avatar_1.jpg',
    subscriptions: [],
    notifications: buildSeedNotifications(),
  };
}

function login(user: UserType): AuthResponse {
  saveUser(user);
  LocalStorageService.saveToken(`${TOKEN_PREFIX}${user.id}`);
  return { etat: true, result: { client: user } };
}

function findUserByPhone(phoneNumber: string): UserType | undefined {
  return Object.values(readDb().users).find(
    (user) => user.phone_number === phoneNumber,
  );
}

export async function getGames(): Promise<CategoryBlocGameType[]> {
  await wait();
  return buildSeedCategoryBlocs();
}

export async function getGamesByID(id: string): Promise<{
  ranking: { myRank: RankingType | null; allRanking: RankingType[] };
  game: Game;
  similarGame: Game[];
}> {
  await wait();
  const games = buildSeedGames();
  const game = games.find((item) => item.id === id);
  if (!game) throw new Error(`Jeu introuvable: ${id}`);

  const categoryIds = game.categories.map((category) => category.id);
  const similarGame = games.filter(
    (item) =>
      item.id !== id &&
      item.categories.some((category) => categoryIds.includes(category.id)),
  );

  return {
    ranking: { myRank: null, allRanking: buildSeedRanking(id) },
    game,
    similarGame,
  };
}

export async function getPricing(): Promise<PricingType[]> {
  await wait();
  return seedPricings;
}

export async function getUser(): Promise<UserType | null> {
  await wait();
  const user = getCurrentUser();
  if (!user && isBrowser() && LocalStorageService.isTokenPresent()) {
    LocalStorageService.clearData();
  }
  return user;
}

export async function updateUser(item: Partial<UserType>): Promise<AuthResponse> {
  await wait();
  const user = getCurrentUser();
  if (!user) return { etat: false, error: ['Utilisateur non connecté'] };
  const updated = { ...user, ...item };
  saveUser(updated);
  LocalStorageService.saveUser(updated);
  return { etat: true, result: { client: updated } };
}

export async function getNotifications(): Promise<NotificationType[]> {
  await wait();
  return getCurrentUser()?.notifications ?? [];
}

export async function readAllNotificationUser(): Promise<AuthResponse> {
  await wait();
  const user = getCurrentUser();
  if (!user) return { etat: false, error: ['Utilisateur non connecté'] };
  saveUser({
    ...user,
    notifications: (user.notifications ?? []).map((notification) => ({
      ...notification,
      isRead: true,
    })),
  });
  return { etat: true };
}

export async function requestAuthentication(
  phoneNumber: string,
): Promise<AuthResponse> {
  await wait();
  return {
    etat: true,
    message: `Code OTP envoyé au ${phoneNumber} (mode démo : n'importe quel code à 4 chiffres)`,
  };
}

export async function verifyAuthentication(
  phoneNumber: string,
  otp: string,
): Promise<AuthResponse> {
  await wait();
  if (!/^\d{4}$/.test(otp)) {
    return { etat: false, error: ['Code OTP invalide'] };
  }
  return login(findUserByPhone(phoneNumber) ?? createUser(phoneNumber));
}

export async function createAnonymousUser(): Promise<AuthResponse> {
  await wait();
  const response = login(createUser());
  LocalStorageService.saveUser(response.result.client);
  return response;
}

export async function biometricLogin(phoneNumber: string) {
  const response = await verifyAuthentication(phoneNumber, '0000');
  return { etat: true, result: response.result.client };
}

export async function sendSubscriptionOtp(): Promise<AuthResponse> {
  await wait();
  return { etat: true, message: 'Code OTP envoyé (mode démo)' };
}

export async function setSubscription({
  forfaitId,
  numberTel,
}: {
  forfaitId: string;
  numberTel?: string;
}): Promise<AuthResponse> {
  await wait();
  const user = getCurrentUser();
  const pricing = seedPricings.find((item) => item.id === forfaitId);
  if (!user || !pricing) {
    return { etat: false, error: ['Abonnement impossible'] };
  }

  const subscriptionId = `sub-${Date.now()}`;
  const startDate = new Date();
  const endDate = new Date(
    startDate.getTime() + pricing.durationForfait * 24 * 60 * 60 * 1000,
  );
  saveUser({
    ...user,
    phone_number: user.phone_number || numberTel || '',
    subscriptions: [
      ...(user.subscriptions ?? []),
      {
        id: subscriptionId,
        forfaitId,
        status: 'PENDING',
        isActive: true,
        startDate: startDate.toISOString(),
        endDate: endDate.toISOString(),
      },
    ],
  });
  return { etat: true, result: { subscriptionId } };
}

export async function getOrders(
  id: string,
): Promise<{ status: string; ref: string }> {
  await wait();
  return { status: StatusEnum.DONE, ref: id };
}

export async function getBanners() {
  return seedBanners;
}

export async function getReviews() {
  return seedReviews;
}

export async function getPromocodes() {
  return seedPromocodes;
}

export async function getOnboarding() {
  return seedOnboarding;
}

export async function getCategories() {
  return seedCategories.map((category, index) => ({
    id: index + 1,
    name: category.name,
    image: `/seed/categories/${category.urlImage}`,
  }));
}
