import { LocalStorageService } from '@/storages/local_storage_service';
import { URLS, USE_SEED_DATA } from '../config';
import * as seed from '@/seeders/api';
import { CategoryBlocGameType } from '@/types/CategoryBlocGameType';
import { Game } from '@/types/GameType';

export async function getGames(): Promise<CategoryBlocGameType[]> {
  if (USE_SEED_DATA) return seed.getGames();

  let token;

  // Vérifie si nous sommes côté client avant d'accéder à localStorage
  if (typeof window !== 'undefined') {
    token = LocalStorageService.getToken(); // Accéder à localStorage uniquement côté client
  }
  // Détermine l'origin à utiliser
  const origin = globalThis.origin;

  const response = await fetch(URLS.GET_GAMES, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
      ...(token && { Authorization: token }),
    },
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const json = await response.json();
  return json.result;
}

export async function getGamesByID(Id: any): Promise<{
  ranking: { myRank: RankingType | null; allRanking: RankingType[] };
  game: Game;
  similarGame: Game[];
}> {
  if (USE_SEED_DATA) return seed.getGamesByID(Id);

  let token;

  // Vérifie si nous sommes côté client avant d'accéder à localStorage
  if (typeof window !== 'undefined') {
    token = LocalStorageService.getToken(); // Accéder à localStorage uniquement côté client
  }
  // Détermine l'origin à utiliser
  const origin = window.origin;

  const response = await fetch(`${URLS.GET_GAMES}/${Id}`, {
    method: 'GET',
    headers: {
      'Content-Type': 'application/json',
      Origin: origin,
      ...(token && { Authorization: token }),
    },
  });
  if (!response.ok) {
    throw new Error(`HTTP error! status: ${response.status}`);
  }
  const json = await response.json();
  return json.result;
}
