export function buildSeedRanking(gameId: string): RankingType[] {
  const seed = [...gameId].reduce((acc, char) => acc + char.charCodeAt(0), 0);
  const now = new Date();
  return rankingPlayers.map((player, index) => ({
    rank: index + 1,
    isMe: false,
    userId: `seed-player-${index + 1}`,
    profil: `avatar_${((seed + index) % 25) + 1}.jpg`,
    pseudo: player.pseudo,
    full_name: player.full_name,
    highScore: 5000 - index * 450 - (seed % 200),
    created_at: now,
    updated_at: now,
  }));
}

